3318: void evalResidual(int ftl, size_t currentPhase, int stepsIntoCurrentPhase)
3319: {
3320:     bool isTerminalPhase = (currentPhase == nkCfg.numberOfPhases - 1);
3321:     if (nkCfg.useTaperedBlending && activePhase.taperedBlending && !isTerminalPhase) {
3322:         auto lastPos = GlobalConfig.n_flow_time_levels - 1;
3323:         double N_t = cast(double)(nkCfg.maxStepsInInitialPhases[currentPhase]);
3324:         double wt = stepsIntoCurrentPhase/N_t;
3325:         auto fcSave = GlobalConfig.flux_calculator;
3326:         // Evaluate residual with blending flux calculator
3327:         if (GlobalConfig.flux_calculator == FluxCalculator.asf) GlobalConfig.high_order_flux_calculator = false;
3328:         GlobalConfig.flux_calculator = nkCfg.blendingFluxCalculator;
3329:         evalResidualWorker(ftl);
3330:         // Next, evaluate residual with main flux calculator
3331:         GlobalConfig.flux_calculator = fcSave;
3332:         if (GlobalConfig.flux_calculator == FluxCalculator.asf) GlobalConfig.high_order_flux_calculator = true;
3333:         evalResidualWorker(to!int(lastPos));
3334:         // And blend...
3335:         foreach (blk; parallel(localFluidBlocks,1)) {
3336:             foreach (ref cell; blk.cells) {
3337:                 foreach (i, ref v; cell.dUdt[ftl]) {
3338:                     v *= (1.0 - wt);
3339:                     v += wt*cell.dUdt[lastPos][i];
3340:                 }
3341:             }
3342:         }
3343:     }
3344:     else {
3345:         if (isTerminalPhase || !activePhase.useBlendingFluxCalculator) {
3346:             evalResidualWorker(ftl);
3347:         }
3348:         else {
3349:             auto fcSave = GlobalConfig.flux_calculator;
3350:             if (GlobalConfig.flux_calculator == FluxCalculator.asf) GlobalConfig.high_order_flux_calculator = false;
3351:             GlobalConfig.flux_calculator = nkCfg.blendingFluxCalculator;
3352:             evalResidualWorker(ftl);
3353:             GlobalConfig.flux_calculator = fcSave;
3354:             if (GlobalConfig.flux_calculator == FluxCalculator.asf) GlobalConfig.high_order_flux_calculator = true;
3355:         }
3356:     }
3357: }

