3553: /**
3554:  * Evaluate J*v via a Frechet derivative with perturbation in imaginary plane.
3555:  *
3556:  * J*v = Im( R(U + sigma*j)/sigma )
3557:  *
3558:  * Authors: KAD and RJG
3559:  * Date: 2022-03-03
3560:  */
3561: void evalComplexMatVecProd(double sigma, bool for_preconditioning, size_t currentPhase, int stepsIntoCurrentPhase)
3562: {
3563:     version(complex_numbers) {
3564:         alias cfg = GlobalConfig;
3565: 
3566:         int gtl = (GlobalConfig.grid_motion == GridMotion.none) ? 0 : 1;
3567: 
3568:         setJacobianEvalSettings(for_preconditioning);
3569: 
3570:         // Make a stack-local copy of conserved quantities info
3571:         size_t nConserved = GlobalConfig.cqi.n;
3572: 
3573:         //writeln("in evalComplexMatVecProd");
3574:         //writefln("sigma= %e", sigma);
3575:         // We perform a Frechet derivative to evaluate J*D^(-1)v
3576:         foreach (blk; parallel(localFluidBlocks,1)) {
3577:             blk.clear_fluxes_of_conserved_quantities();
3578:             foreach (i, cell; blk.cells) cell.clear_source_vector();
3579:             size_t startIdx = 0;
3580:             foreach (i, cell; blk.cells) {
3581:                 cell.U[1][] = cell.U[0][];
3582:                 foreach (ivar; 0 .. nConserved) {
3583:                     cell.U[1][ivar] += complex(0.0, sigma * blk.zed[startIdx+ivar].re);
3584:                 }
3585:                 cell.decode_conserved(gtl, 1, blk.omegaz);
3586:                 startIdx += nConserved;
3587:             }
3588: 
3589:             if (blk.myConfig.grid_motion != GridMotion.none) {
3590:                 // TODO: Some code paths in decode_conserved depend on the grid properties
3591:                 // so this should really be done before the fluid variabes are handled
3592:                 foreach (i, vtx; blk.vertices) {
3593:                     if (!vtx.solve_position) { 
3594:                         // the position of this vertex is solved for in a different block
3595:                         continue;
3596:                     }
3597:                     vtx.pos[1] = vtx.pos[0];
3598:                     vtx.pos[1].x += complex(0, sigma * blk.zed[startIdx].re);
3599:                     startIdx++;
3600:                     vtx.pos[1].y += complex(0, sigma * blk.zed[startIdx].re);
3601:                     startIdx++;
3602:                     if (blk.myConfig.dimensions == 3) {
3603:                         vtx.pos[1].z += complex(0, sigma * blk.zed[startIdx].re); 
3604:                         startIdx++;
3605:                     }
3606:                 }
3607:             }
3608:         }
3609:         evalResidual(1, currentPhase, stepsIntoCurrentPhase);
3610:         foreach (blk; parallel(localFluidBlocks,1)) {
3611:             size_t startIdx = 0;
3612:             foreach (cell; blk.cells) {
3613:                 foreach (ivar; 0 .. nConserved) {
3614:                     blk.zed[startIdx+ivar] = cell.dUdt[1][ivar].im/(sigma);
3615:                 }
3616:                 startIdx += nConserved;
3617:             }
3618: 
3619:             if (blk.myConfig.grid_motion != GridMotion.none) {
3620:                 foreach (vtx; blk.vertices) {
3621:                     if (!vtx.solve_position) { continue; }
3622:                     blk.zed[startIdx] = vtx.vel[1].x.im/(sigma);
3623:                     startIdx++;
3624:                     blk.zed[startIdx] = vtx.vel[1].y.im/(sigma);
3625:                     startIdx++;
3626:                     if (blk.myConfig.dimensions == 3) {
3627:                         blk.zed[startIdx] = vtx.vel[1].z.im/(sigma);
3628:                         startIdx++;
3629:                     }
3630:                 }
3631:             }
3632:             // we must explicitly remove the imaginary components from the cell and interface flowstates
3633:             foreach(cell; blk.cells) { cell.fs.clear_imaginary_components(); }
3634:             foreach(bc; blk.bc) {
3635:                 foreach(ghostcell; bc.ghostcells) { ghostcell.fs.clear_imaginary_components(); }
3636:             }
3637:             foreach(face; blk.faces) { face.fs.clear_imaginary_components(); }
3638: 
3639:             if (blk.myConfig.grid_motion != GridMotion.none) {
3640:                 foreach(vtx; blk.vertices) { 
3641:                     vtx.pos[0].clear_imaginary_components();
3642:                     // vtx.vel[0].clear_imaginary_components();
3643:                     vtx.pos[1].clear_imaginary_components();
3644:                     // vtx.vel[1].clear_imaginary_components();
3645:                 }
3646:             }
3647:         }
3648:         setResidualEvalSettings();
3649:     } else {
3650:         throw new Error("Oops. Steady-State Solver setting: useComplexMatVecEval is not compatible with real-number version of the code.");

628:     void source_terms(ref const(FlowState) fs, ref const(FlowGradients) grad, const number ybar,
629:                       const number dwall, const number L_min, const number L_max,
630:                       ref number[] source) const {
631:         /*
632:         Spalart Allmaras Source Terms:
633:         Notes:
634:            - This term consists of Production - Destruction +
635:              compressible dissipation, the blue, red, and magenta terms
636:              from Gibbons, 2019, equation 2.32
637:         */
638: 
639:         number nuhat = fs.turb[0];
640:         number rho = fs.gas.rho;
641:         number nu = fs.gas.mu/rho;
642:         number chi = nuhat/nu;
643:         number chi_cubed = chi*chi*chi;
644:         number fv1 = chi_cubed/(chi_cubed + cv1_cubed);
645:         number fv2 = 1.0 - chi/(1.0 + chi*fv1);
646:         number ft2 = compute_ft2(chi);
647:         number nut = nuhat*fv1;
648: 
649:         number d = compute_d(nut,nu,grad.vel,dwall,L_min,L_max,fv1,fv2,ft2);
650:         number Shat_by_nuhat = compute_Shat_mulitplied_by_nuhat(grad, nuhat, nu, d, fv1, fv2);
651:         number production = rho*cb1*(1.0 - ft2)*Shat_by_nuhat;
652: 
653:         number r = compute_r(Shat_by_nuhat, nuhat, d);
654:         number g = r + cw2*(pow(r,6.0) - r);
655:         number fw = (1.0 + cw3_to_the_sixth)/(pow(g,6.0) +  cw3_to_the_sixth);
656:         fw = g*pow(fw, 1.0/6.0);
657:         number destruction = rho*(cw1*fw - cb1/kappa/kappa*ft2)*(nuhat*nuhat/d/d);
658: 
659:         //// No axisymmetric corrections terms in dS/dxi dS/dxi
660:         number nuhat_gradient_squared = 0.0;
661:         foreach(i; 0 .. 3) nuhat_gradient_squared+=grad.turb[0][i]*grad.turb[0][i];
662:         number dissipation = cb2/sigma*rho*nuhat_gradient_squared;
663: 
664:         number T = production - destruction + dissipation;
665:         //debug {
666:         //    if (!isFinite(T.re)) {
667:         //        writeln("Turbulence source term is NaN.");
668:         //        writeln("  r=", r, " fw=", fw, " rho=", rho, " cw1=", cw1, " cb1=", cb1);
669:         //        writeln("  kappa=", kappa, " ft2=", ft2, " nuhat=", nuhat, " d=", d, " Shat_by_nuhat=", Shat_by_nuhat);
670:         //        writeln("  production=", production, " destruction=", destruction, " dissipation=", dissipation);
671:         //        writeln("  T=", T);
672:         //        throw new Error("Turbulence source term is not finite.");
673:         //    }
674:         //}
675:         source[0] = T;
676:         return;
677:     } // end source_terms()

