784:     immutable double cw2 = 0.3;
785:     immutable double cw3 = 2.0;
786:     immutable double cw3_to_the_sixth = cw3*cw3*cw3*cw3*cw3*cw3;
787:     immutable double cv1 = 7.1;
788:     immutable double cv1_cubed = cv1*cv1*cv1;
