1065:     @nogc override number
1066:     compute_Shat_mulitplied_by_nuhat(ref const(FlowGradients) grad, const number nuhat, const number nu,
1067:                  const number d, const number fv1, const number fv2) const pure {
1068:         /*
1069:         The Edwards variant of Spalart-Allmaras contains a definition of Shat
1070:         that is singular when nuhat is equal to zero, such as during the Newton Krylov
1071:         startup phase where the boundary conditions are diffused into the flow.
1072: 
1073:         Since Shat*nuhat is always non-singular and both the Edwards and normal models
1074:         need it, we compute that instead.
1075:         */
1076:         number S = 0.0;
1077:         foreach(i; 0 .. 3) {
1078:             foreach(j; 0 .. 3) {
1079:                  S += (grad.vel[i][j] + grad.vel[j][i])*grad.vel[i][j];
1080:             }
1081:         }
1082:         number div = grad.vel[0][0] + grad.vel[1][1] + grad.vel[2][2];
1083:         S -= 2.0/3.0*div*div;
1084:         number Shat_by_nuhat = sqrt(S)*(nu + fv1*nuhat);
1085:         return Shat_by_nuhat;
1086:     }
1087: 
1088:     @nogc override number
1089:     compute_r(const number Shat_by_nuhat, const number nuhat, const number d) const pure {
1090:         number normal_r = super.compute_r(Shat_by_nuhat, nuhat, d);
1091:         number r = tanh(normal_r)/tanh(1.0);
1092:         return r;
1093:     }
1094: }
